  function formatBytes(v){const n=Math.max(0,Number(v)||0);if(n<1024)return `${n} Б`;if(n<1024*1024)return `${(n/1024).toFixed(n<10240?1:0)} КБ`;return `${(n/1024/1024).toFixed(1)} МБ`;}
  function prettyDiagnosticLogLines(raw){return String(raw||'').split(/\r?\n/).filter(Boolean).map(line=>{const m=line.match(/^\[([^\]]+)\]\s+(.*)$/);let text=line,body=line;if(m){body=m[2];const d=new Date(m[1]);text=Number.isNaN(d.getTime())?line:`${d.toLocaleTimeString('ru-RU',{hour12:false})}  ${body}`;}const isError=/(^|\s)ERROR(?:\s|$)|(?:^|\s)[A-Z0-9_]*_ERROR(?:\s|$)|UNCAUGHT_EXCEPTION|UNHANDLED_REJECTION|FATAL/i.test(body);return{text,isError};});}
  function updateDiagnosticLog(raw,size,forceBottom=false,debugMode=null){const el=$('diagnosticLog');if(!el)return;const nearBottom=el.scrollHeight-el.scrollTop-el.clientHeight<45;const lines=prettyDiagnosticLogLines(raw);const enabled=debugMode===null?Boolean($('debugMode')?.checked):Boolean(debugMode);if(lines.length){const signature=lines.map(x=>(x.isError?'E:':'L:')+x.text).join('\n');if(el.dataset.signature!==signature){el.replaceChildren();for(const line of lines){const span=document.createElement('span');span.className='diag-log-line'+(line.isError?' error':'');span.textContent=line.text;el.append(span);}el.dataset.signature=signature;}}else{const next=enabled?'Журнал пока пуст.':'Включите режим отладки, чтобы видеть логи.';if(el.textContent!==next||el.dataset.signature){el.textContent=next;el.dataset.signature='';}}if(forceBottom||nearBottom)el.scrollTop=el.scrollHeight;if($('diagnosticLogSize'))$('diagnosticLogSize').textContent=`Размер журнала: ${formatBytes(size)}`;}
