  async function refreshSensorHistoryModal(){const st=sensorHistoryState,d=st.device;if(!d)return;const chart=$('sensorHistoryChart'),empty=$('sensorHistoryEmpty'),stats=$('sensorHistoryStats');chart.innerHTML='<div class="history-loading">Загрузка…</div>';empty.classList.add('hidden');stats.innerHTML='';try{const data=await fetchSensorHistory(d.id,st.instance,st.hours,true),unit=data.unitText||'',current=data.stats?.current;const title=$('sensorHistoryTitle'),name=$('sensorHistoryName');if(title)title.textContent=`${data.label||'Показатель'} ${historyValue(current,unit)}`;if(name)name.textContent=`${d.name||'Датчик'} · ${d.room||'Без комнаты'}${historyUpdatedText(d,st.instance)}`;if(!data.points?.length){chart.innerHTML='';empty.textContent='За выбранный период точек пока нет.';empty.classList.remove('hidden');return;}chart.innerHTML=renderHistoryChart(data,st.instance,st.hours,'modal');bindHistoryTooltip(chart,data,st.hours,'modal');stats.innerHTML=historyStatsHtml(data,st.instance)+historyQualityMarkup(data,st.instance);}catch(e){chart.innerHTML='';empty.textContent=e?.message||'Не удалось загрузить историю.';empty.classList.remove('hidden');}}
  function groupAggregate(d){if(!d?.isGroup)return null;const members=groupMembers(d),online=members.filter(x=>x.online!==false),powerKnown=members.filter(x=>typeof x.power==='boolean'),on=powerKnown.filter(x=>x.power===true).length,brightnessValues=members.map(x=>Number(x.brightness?.value)).filter(Number.isFinite),temps=members.map(x=>x.color?.stateInstance==='temperature_k'?Number(x.color?.stateValue):NaN).filter(Number.isFinite),rgbs=members.map(x=>deviceRgb(x)).filter(Number.isFinite);const same=v=>v.length&&v.every(x=>Math.round(x)===Math.round(v[0]));return{members,onlineCount:online.length,total:members.length,powerKnown:powerKnown.length,on,brightness:brightnessValues.length?(same(brightnessValues)?Math.round(brightnessValues[0]):'mixed'):null,temperature:temps.length?(same(temps)?Math.round(temps[0]):'mixed'):null,color:rgbs.length?(same(rgbs)?Math.round(rgbs[0]):'mixed'):null};}
