  function unitText(r){if(r.unitText)return r.unitText;if(['brightness','open','volume','humidity'].includes(r.instance))return'%';if(r.instance==='temperature')return'°C';return'';}
  function syncRangeVisual(inp){if(!inp)return;const min=Number(inp.min),max=Number(inp.max),value=Number(inp.value);const pct=Number.isFinite(min)&&Number.isFinite(max)&&max>min&&Number.isFinite(value)?Math.max(0,Math.min(100,(value-min)/(max-min)*100)):50;inp.style.setProperty('--range-pct',`${pct}%`);}
