    if(d.isHub){const linked=hubCandidates(d);if(linked.length){const sec=document.createElement('section');sec.className='detail-section';sec.innerHTML='<div class="detail-section-title">Устройства пульта</div>';const list=document.createElement('div');list.className='detail-linked-list';for(const x of linked){const row=document.createElement('button');row.type='button';row.innerHTML='<span></span><small></small><b>›</b>';row.querySelector('span').textContent=x.name;row.querySelector('small').textContent=prettyType(x.type)+(x.online===false?' · Не в сети':'');row.addEventListener('click',()=>openDeviceDetail(x));list.append(row);}sec.append(list);body.append(sec);}}
