    const icon=iconFor(d);
    card.innerHTML=`<div class="device-top"><div class="device-idblock"><img class="device-icon" src="../static/icons/${icon}"><div class="compact-title-wrap"><div class="device-name"></div><div class="device-kind"></div></div></div><div class="device-side"><span class="entity-drag-handle" title="Перетащить" aria-hidden="true">⋮⋮</span></div></div><div class="compact-card-mid"><div><div class="compact-state"></div><div class="compact-state-note"></div></div><div class="compact-metrics"></div></div><div class="compact-capabilities"></div><div class="compact-inline"></div><div class="command-feedback hidden"></div><div class="compact-card-actions"><button type="button" class="compact-open">Подробнее <span>›</span></button></div>`;
