    const state=card.querySelector('.compact-state'),stateNote=card.querySelector('.compact-state-note'),stateValue=stateText(d);state.textContent=stateValue;state.classList.toggle('offline',entityOffline(d)||stateValue==='Не в сети');if(d.power===true)state.classList.add('on');if(stateValue==='—')state.classList.add('hidden');if(entityOffline(d)){state.title=lastSeenText(d);stateNote.textContent=lastSeenText(d);stateNote.title=lastSeenText(d);}else stateNote.classList.add('hidden');
    if(hidden){const tag=document.createElement('span');tag.className='hidden-entity-badge';tag.textContent='Скрыто';tag.title='Устройство скрыто из обычного списка';card.querySelector('.compact-title-wrap').append(tag);}
    const caps=capabilityProfile(d),capRoot=card.querySelector('.compact-capabilities');const capLabels=[];if(caps.power)capLabels.push('Питание');if(caps.brightness)capLabels.push('Яркость');if(caps.colorRgb)capLabels.push('RGB');if(caps.colorTemperature)capLabels.push('Белый');if(caps.open)capLabels.push('Положение');if(caps.modes.length)capLabels.push('Режимы');if(caps.toggles.length)capLabels.push('Переключатели');if(caps.numericProps.length)capLabels.push(`${caps.numericProps.length} ${pluralRu(caps.numericProps.length,'датчик','датчика','датчиков')}`);for(const label of capLabels.slice(0,4)){const s=document.createElement('span');s.textContent=label;capRoot.append(s);}if(!capRoot.children.length)capRoot.classList.add('is-empty');
    const side=card.querySelector('.device-side');const power=quickPowerButton(d);if(power){power.classList.add('compact-top-power');side.append(power);}const favBtn=document.createElement('button');favBtn.type='button';favBtn.className='favorite-toggle';favBtn.title='Избранное';favBtn.setAttribute('aria-label','Избранное');favBtn.textContent='★';favBtn.classList.toggle('active',isFavoriteEntity(d));favBtn.setAttribute('aria-pressed',isFavoriteEntity(d)?'true':'false');favBtn.addEventListener('click',e=>{e.stopPropagation();toggleFavoriteEntity(d);});side.append(favBtn);
