    const profile=capabilityProfile(d);let quickRange=null;if(profile.brightness)quickRange=compactInlineRange(d,profile.brightness);else if(profile.open)quickRange=compactInlineRange(d,profile.open);if(quickRange)card.querySelector('.compact-inline').append(quickRange);else card.querySelector('.compact-inline').classList.add('is-empty');
