  function renderSearchSuggestions(){const root=$('searchSuggestions'),input=$('search');if(!root||!input)return;const raw=input.value.trim(),q=raw.toLocaleLowerCase('ru');root.innerHTML='';if(!q){root.classList.add('hidden');return;}const seen=new Set(),items=[],visible=allEntities().filter(d=>showHidden||!isHiddenEntity(d));for(const d of visible){const hay=`${d.name||''} ${d.room||''} ${prettyType(d.type)} ${d.type||''}`.toLocaleLowerCase('ru');if(!hay.includes(q))continue;items.push({kind:'entity',label:d.name||'Без названия',sub:`${d.room||'Без комнаты'} · ${d.isGroup?'Группа':prettyType(d.type)}`,entity:d});if(items.length>=4)break;}for(const room of orderedRooms([...new Set(visible.map(d=>d.room||'Без комнаты'))])){if(items.length>=6)break;if(room.toLocaleLowerCase('ru').includes(q)&&!seen.has('r:'+room)){seen.add('r:'+room);items.push({kind:'room',label:room,sub:'Комната',room});}}for(const [id,label] of CAT){if(id==='all'||items.length>=7)break;if(!label.toLocaleLowerCase('ru').includes(q)||!categoryCount(id))continue;items.push({kind:'category',label,sub:'Тип устройств',category:id});}if(!items.length){root.classList.add('hidden');return;}for(const item of items){const b=document.createElement('button');b.type='button';b.className='search-suggestion';b.setAttribute('role','option');b.innerHTML='<span></span><small></small><b>›</b>';b.querySelector('span').textContent=item.label;b.querySelector('small').textContent=item.sub;b.addEventListener('mousedown',e=>e.preventDefault());b.addEventListener('click',()=>{root.classList.add('hidden');if(item.kind==='room'){activeRoom=item.room;activeCategory='all';input.value='';persistDashboardPrefs();renderFilters();renderDevices();}else if(item.kind==='category'){activeRoom='all';activeCategory=item.category;input.value='';persistDashboardPrefs();renderFilters();renderDevices();}else openDeviceDetail(item.entity);});root.append(b);}root.classList.remove('hidden');}
