    const shownRooms=activeRoom==='all'?rooms.length:1;$('deviceCount').textContent=`${filtered.length} из ${all.length} · ${filteredGroups.length} ${pluralRu(filteredGroups.length,'группа','группы','групп')} · ${shownRooms} ${pluralRu(shownRooms,'комната','комнаты','комнат')}`;
    renderSummary();renderRoomJump(allRooms);
