      const memberOfAny=new Set();for(const g of roomGroups)for(const id of (g.memberIds||[]))if(roomDevices.some(d=>String(d.id)===String(id)))memberOfAny.add(String(id));
      const roomHubs=roomDevices.filter(d=>d.isHub);const hubGrouped=new Set();const hubClusters=[];if(roomHubs.length===1){const hub=roomHubs[0];const linked=hubCandidates(hub).filter(x=>roomDevices.some(d=>String(d.id)===String(x.id)));for(const x of linked)hubGrouped.add(String(x.id));hubClusters.push([hub,linked]);}
