      const head=document.createElement('div');head.className='room-head';head.innerHTML=`<div class="room-title-wrap"><span class="room-chevron">⌄</span><div class="room-title"></div></div><div class="room-head-side"><div class="room-order-actions"><button type="button" class="room-order-btn room-up" title="Поднять комнату" aria-label="Поднять комнату">↑</button><button type="button" class="room-order-btn room-down" title="Опустить комнату" aria-label="Опустить комнату">↓</button></div><div class="room-count"></div></div>`;head.querySelector('.room-title').textContent=room;const offCount=roomDevices.filter(d=>d.online===false).length,lightOn=roomDevices.filter(d=>capabilityProfile(d).lighting&&d.power===true).length;head.querySelector('.room-count').textContent=`${roomDevices.length} ${pluralRu(roomDevices.length,'устройство','устройства','устройств')}${roomGroups.length?` · ${roomGroups.length} ${pluralRu(roomGroups.length,'группа','группы','групп')}`:''}${lightOn?` · ${lightOn} свет ${lightOn===1?'включён':'включено'}`:''}${offCount?` · ${offCount} не в сети`:''}`;const roomIndex=rooms.indexOf(room),upBtn=head.querySelector('.room-up'),downBtn=head.querySelector('.room-down');if(upBtn)upBtn.disabled=roomIndex<=0;if(downBtn)downBtn.disabled=roomIndex>=rooms.length-1;upBtn?.addEventListener('click',e=>{e.stopPropagation();moveRoomStep(room,-1);});downBtn?.addEventListener('click',e=>{e.stopPropagation();moveRoomStep(room,1);});head.addEventListener('click',e=>{if(e.target.closest('button,input,select'))return;toggleRoom(room);});section.append(head);makeRoomSortable(section,room);
