  window.addEventListener('message',evt=>{const msg=evt.data;if(!msg||msg.channel!=='ysh')return;if(msg.type==='snapshot')applySnapshot(msg.payload);else if(msg.type==='globalSettings'){if(msg.payload?.token)$('dashboardToken').value=msg.payload.token;renderTokenExpiry({expiresAt:msg.payload?.tokenExpiresAt,lifetimeSeconds:msg.payload?.tokenLifetimeSeconds,capturedAt:msg.payload?.tokenExpiryCapturedAt});actionRefreshSeconds=[0,15,30,45,60,120,300].includes(Number(msg.payload?.actionRefreshSeconds))?Number(msg.payload.actionRefreshSeconds):30;syncActionRefreshControl();}else if(msg.type==='status')setConnection(msg.payload?.text||'',msg.payload?.cls||'');else if(msg.type==='dashboardLoading'){loading=true;$('refreshDevices').disabled=true;renderDevices();}else if(msg.type==='dashboardDevices'){loading=false;$('refreshDevices').disabled=false;devices=Array.isArray(msg.payload?.devices)?msg.payload.devices:[];groups=Array.isArray(msg.payload?.groups)?msg.payload.groups:[];scenarios=Array.isArray(msg.payload?.scenarios)?msg.payload.scenarios:[];updateLastOnline([...devices,...groups]);lastUpdatedAt=Date.now();$('summaryUpdated')?.classList.add('updated-flash');setTimeout(()=>$('summaryUpdated')?.classList.remove('updated-flash'),500);setConnection(msg.payload?.message||'Устройства загружены.','ok');lastUpdatedAt=Date.now();renderFilters();renderDevices();renderScenarios();renderFavorites();}else if(msg.type==='dashboardError'){loading=false;$('refreshDevices').disabled=false;setConnection(msg.payload?.message||'Ошибка загрузки.','error');toast(msg.payload?.message||'Ошибка',true);}else if(msg.type==='dashboardCommandResult'){const handled=resolveLatestCommand(Boolean(msg.payload?.ok),msg.payload?.message||'');if(!msg.payload?.ok&&!handled)toast(msg.payload?.message||'Ошибка команды.',true);}else if(msg.type==='tokenStatus'){$('saveToken').disabled=false;if(msg.payload?.tokenExpiry)renderTokenExpiry(msg.payload.tokenExpiry);const valid=Boolean(msg.payload?.valid),pill=$('connectionPill');pill.textContent=valid?'Подключено':'Ошибка';pill.className='pill '+(valid?'ok':'error');setConnection(msg.payload?.message||(valid?'Токен работает.':'Ошибка токена.'),valid?'ok':'error');setSideStatus(valid,valid?'Подключено к Яндексу':'Ошибка подключения');}else if(msg.type==='event'&&msg.payload?.type==='backendReady')setSideStatus(true,'Backend подключен');});
  window.addEventListener('beforeunload',()=>{if(!fullResetInProgress){const main=document.querySelector('.main');if(main)pageScroll[activePage]=main.scrollTop||0;writeLocalDashboardPrefs();}stopDiagnosticsPolling();stopAutoRefresh();});
  document.querySelectorAll('input[type=range]').forEach(wireRangeVisual);restoreExpandedGroups();restoreDashboardPrefs();syncAutoRefreshControl();syncActionRefreshControl();syncSidebarSettings();setActivePage(startPage);scheduleAutoRefresh();const mainScroll=document.querySelector('.main');mainScroll?.addEventListener('scroll',()=>{pageScroll[activePage]=mainScroll.scrollTop||0;},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')scheduleAutoRefresh();});const first=api()?.getSnapshot?.();if(first)applySnapshot(first);else setSideStatus(isStandalone?true:false,isStandalone?'Подключение к локальному backend…':'Откройте панель из Stream Dock');api()?.ready?.();
